1	import type { PaneNode } from "@/lib/split-layout";
2	import {
3	  getSwipeSelectionRoot,
4	  hasExpandedTextSelectionWithin,
5	  isInsideHorizontalScrollRegion,
6	} from "@/lib/swipe-gesture-targets";
7	import { getAdjacentPaneId } from "./splitPaneCommands";
8	
9	/** Horizontal travel that declares the gesture and takes pointer capture. */
10	export const WORKSPACE_SWIPE_INTENT_PX = 12;
11	/** Distance alone commits a pane change past this share of the width. */
12	export const WORKSPACE_SWIPE_PANE_COMMIT_RATIO = 0.33;
13	/** A fling commits from this much shorter distance… */
14	export const WORKSPACE_SWIPE_FLING_MIN_RATIO = 0.12;
15	/** …when it is still travelling at least this fast, in the same direction. */
16	export const WORKSPACE_SWIPE_FLING_VELOCITY_PX_PER_SEC = 450;
17	/**
18	 * The Command Center opens on physical rightward distance only. Velocity can
19	 * complete a short pane swipe but must never promote one to this destination,
20	 * or a quick flick would replace the whole surface.
21	 */
22	export const WORKSPACE_SWIPE_COMMAND_CENTER_RATIO = 0.68;
23	/**
24	 * How recent the last movement sample must be to describe the release. A finger
25	 * that travelled fast and then rested is no longer flinging, so a stale sample
26	 * decays to zero and the release is judged on distance alone.
27	 */
28	export const WORKSPACE_SWIPE_VELOCITY_STALE_MS = 100;
29	export const WORKSPACE_SWIPE_SETTLE_MS = 250;
30	export const WORKSPACE_SWIPE_SETTLE_EASING = "cubic-bezier(0.22, 1, 0.36, 1)";
31	
32	/** Marks the host so the horizontal-scroller walk stops at the surface. */
33	export const WORKSPACE_SWIPE_HOST_SELECTOR = "[data-workspace-swipe-host]";
34	
35	const WORKSPACE_SWIPE_IGNORED_SELECTOR = [
36	  "input",
37	  "textarea",
38	  "select",
39	  '[contenteditable="true"]',
40	  '[role="slider"]',
41	  '[data-sidebar="panel"]',
42	  '[data-sidebar="trigger"]',
43	  // Vaul drawers and Radix overlay content own their own gestures.
44	  "[data-vaul-drawer]",
45	  "[data-vaul-no-drag]",
46	  '[role="dialog"]',
47	  '[role="alertdialog"]',
48	  '[role="menu"]',
49	  '[role="listbox"]',
50	  "[data-radix-popper-content-wrapper]",
51	  // Explicit opt-out for surfaces that need the whole horizontal axis.
52	  "[data-no-workspace-swipe]",
53	].join(", ");
54	
55	export type WorkspaceSwipeDirection = "left" | "right";
56	
57	export function readWorkspaceSwipeDirection(
58	  deltaX: number,
59	): WorkspaceSwipeDirection | null {
60	  if (deltaX === 0) {
61	    return null;
62	  }
63	  return deltaX > 0 ? "right" : "left";
64	}
65	
66	/** True once a move is unambiguously horizontal: the capture point. */
67	export function hasWorkspaceSwipeIntent(
68	  deltaX: number,
69	  deltaY: number,
70	): boolean {
71	  const absDeltaX = Math.abs(deltaX);
72	  return (
73	    absDeltaX >= WORKSPACE_SWIPE_INTENT_PX &&
74	    absDeltaX > Math.abs(deltaY) * 1.25
75	  );
76	}
77	
78	/** True once a move is unambiguously vertical: scrolling keeps the pointer. */
79	export function abandonsWorkspaceSwipe(
80	  deltaX: number,
81	  deltaY: number,
82	): boolean {
83	  const absDeltaY = Math.abs(deltaY);
84	  return (
85	    absDeltaY > WORKSPACE_SWIPE_INTENT_PX && absDeltaY > Math.abs(deltaX) * 1.15
86	  );
87	}
88	
89	export type WorkspaceSwipeTarget =
90	  | { kind: "pane"; direction: WorkspaceSwipeDirection }
91	  | { kind: "command-center" };
92	
93	export type WorkspaceSwipeOutcome = WorkspaceSwipeTarget | { kind: "cancel" };
94	
95	export interface WorkspaceSwipeInput {
96	  /** Signed horizontal travel in px; positive is rightward. */
97	  deltaX: number;
98	  /** Signed horizontal velocity in px/s; positive is rightward. */
99	  velocityX: number;
100	  /** Physical width the gesture travels across. */
101	  width: number;
102	  /** Whether a long rightward drag may open the Command Center here. */
103	  allowsCommandCenter: boolean;
104	}
105	
106	/** Where a release right now would land, ignoring commit thresholds. */
107	export function resolveWorkspaceSwipeTarget({
108	  deltaX,
109	  width,
110	  allowsCommandCenter,
111	}: Omit<WorkspaceSwipeInput, "velocityX">): WorkspaceSwipeTarget | null {
112	  if (!Number.isFinite(width) || width <= 0) {
113	    return null;
114	  }
115	  const direction = readWorkspaceSwipeDirection(deltaX);
116	  if (direction === null) {
117	    return null;
118	  }
119	  if (
120	    allowsCommandCenter &&
121	    deltaX / width >= WORKSPACE_SWIPE_COMMAND_CENTER_RATIO
122	  ) {
123	    return { kind: "command-center" };
124	  }
125	  return { kind: "pane", direction };
126	}
127	
128	/** The velocity a release is judged on: the last sample, unless it is stale. */
129	export function readReleaseVelocity(
130	  velocityX: number,
131	  idleMsBeforeRelease: number,
132	): number {
133	  return idleMsBeforeRelease > WORKSPACE_SWIPE_VELOCITY_STALE_MS
134	    ? 0
135	    : velocityX;
136	}
137	
138	/** The destination a release commits to, or `cancel` to restore the source. */
139	export function decideWorkspaceSwipe(
140	  input: WorkspaceSwipeInput,
141	): WorkspaceSwipeOutcome {
142	  const target = resolveWorkspaceSwipeTarget(input);
143	  if (target === null) {
144	    return { kind: "cancel" };
145	  }
146	  if (target.kind === "command-center") {
147	    return target;
148	  }
149	  const ratio = Math.abs(input.deltaX) / input.width;
150	  const isFling =
151	    ratio >= WORKSPACE_SWIPE_FLING_MIN_RATIO &&
152	    Math.abs(input.velocityX) >= WORKSPACE_SWIPE_FLING_VELOCITY_PX_PER_SEC &&
153	    Math.sign(input.velocityX) === Math.sign(input.deltaX);
154	  return ratio >= WORKSPACE_SWIPE_PANE_COMMIT_RATIO || isFling
155	    ? target
156	    : { kind: "cancel" };
157	}
158	
159	/**
160	 * The pane a swipe moves to, in the workspace's persisted reading order.
161	 * Dragging rightward reveals the previous pane (the content follows the
162	 * finger), dragging leftward the next one; both wrap, exactly like the
163	 * keyboard pane-focus commands.
164	 */
165	export function resolveWorkspaceSwipePaneId(
166	  panes: readonly PaneNode[],
167	  focusedPaneId: string,
168	  direction: WorkspaceSwipeDirection,
169	): string | null {
170	  return getAdjacentPaneId(
171	    panes,
172	    focusedPaneId,
173	    direction === "right" ? -1 : 1,
174	  );
175	}
176	
177	/** Position announcement for the polite live region after a commit. */
178	export function describeWorkspacePosition(
179	  panes: readonly PaneNode[],
180	  paneId: string,
181	): string | null {
182	  const index = panes.findIndex((pane) => pane.paneId === paneId);
183	  return index === -1 ? null : `Workspace ${index + 1} of ${panes.length}`;
184	}
185	
186	/**
187	 * Whether the gesture must leave this pointer alone: editable and value-drag
188	 * controls, an expanded text selection, horizontal scrollers, sidebar and
189	 * overlay surfaces that own their own gestures, and explicit opt-outs.
190	 */
191	export function shouldIgnoreWorkspaceSwipeTarget(
192	  target: EventTarget | null,
193	): boolean {
194	  if (!(target instanceof Element)) {
195	    return false;
196	  }
197	  if (target.closest(WORKSPACE_SWIPE_IGNORED_SELECTOR) !== null) {
198	    return true;
199	  }
200	  const selectionRoot = getSwipeSelectionRoot(target);
201	  if (selectionRoot !== null && hasExpandedTextSelectionWithin(selectionRoot)) {
202	    return true;
203	  }
204	  return isInsideHorizontalScrollRegion(target, WORKSPACE_SWIPE_HOST_SELECTOR);
205	}
206

