149	 *
150	 * Only the source is interactive. The incoming surface is an inert shell drawn
151	 * from pane metadata (see CompactWorkspacePreviewSurface), and the real
152	 * destination mounts only once the route commits, so a drag never starts a
153	 * thread subscription, a plugin runtime, or a composer focus.
154	 */
155	export function CompactWorkspaceSwipeHost({
156	  children,
157	  contentKey,
158	  panes,
159	  focusedPaneId,
160	  allowsCommandCenter,
161	  returnPaneId,
162	  onFocusPane,
163	  onOpenCommandCenter,
164	  onReturnFromCommandCenter,
165	}: CompactWorkspaceSwipeHostProps) {
