168	  const sourceRef = useRef<HTMLDivElement>(null);
169	  const previewLayerRef = useRef<HTMLDivElement>(null);
170	  const sessionRef = useRef<SwipeSession | null>(null);
171	  const previewRef = useRef<SwipePreview | null>(null);
172	  const teardownRef = useRef<(() => void) | null>(null);
173	  const settleTimerRef = useRef<number | null>(null);
174	  // Stamped with the content it was resolved against, so a surface that changes
175	  // mid-gesture drops the travelling shell on the very same render instead of
176	  // one effect later.
177	  const [previewState, setPreviewState] = useState<{
178	    contentKey: string;
179	    preview: SwipePreview;
180	  } | null>(null);
181	  const preview =
182	    previewState !== null && previewState.contentKey === contentKey
