224	
225	  const restLayers = () => {
226	    clearLayer(sourceRef.current);
227	    clearLayer(previewLayerRef.current);
228	    previewRef.current = null;
229	    setPreviewState(null);
230	  };
231	
232	  const applyMotion = (deltaX: number, width: number, settling: boolean) => {
233	    if (prefersReducedMotion) {
234	      // Reduced motion keeps the behavior and drops the travelling surface:
235	      // the incoming shell simply states itself, quietly.
236	      const layer = previewLayerRef.current;
