241	    }
242	    moveLayer(sourceRef.current, deltaX, settling);
243	    const current = previewRef.current;
244	    if (current !== null) {
245	      const entering = current.direction === "right" ? -width : width;
246	      moveLayer(previewLayerRef.current, deltaX + entering, settling);
247	    }
248	  };
249	
250	  const afterSettle = (run: () => void) => {
251	    if (prefersReducedMotion) {
252	      run();
253	      return;
254	    }
255	    settleTimerRef.current = window.setTimeout(() => {
256	      settleTimerRef.current = null;
257	      run();
258	    }, WORKSPACE_SWIPE_SETTLE_MS);
259	  };
260	
261	  const resolvePreview = (
262	    deltaX: number,
263	    width: number,
264	  ): SwipePreview | null => {
265	    const direction = readWorkspaceSwipeDirection(deltaX);
266	    if (direction === null) {
267	      return null;
268	    }
269	    // A gesture-opened Command Center offers exactly one move: back to the pane
270	    // the gesture started from. Traversal resumes from there.
271	    if (returnPaneId !== null) {
272	      return direction === "left"
273	        ? {
274	            direction,
275	            destination: {
276	              kind: "return",
277	              paneId: returnPaneId,
278	              content: findPaneContent(panes, returnPaneId),
279	            },
280	          }
281	        : null;
282	    }
283	    const target = resolveWorkspaceSwipeTarget({
284	      deltaX,
285	      width,
286	      allowsCommandCenter,
287	    });
288	    if (target === null) {
289	      return null;
290	    }
291	    if (target.kind === "command-center") {
292	      return { direction: "right", destination: target };
293	    }
294	    const paneId = resolveWorkspaceSwipePaneId(
295	      panes,
296	      focusedPaneId,
297	      target.direction,
298	    );
299	    if (paneId === null) {
300	      // Nothing to traverse to. A long rightward drag can still reach the
301	      // Command Center, so show its shell for the whole travel instead of
302	      // popping it in at the threshold.
303	      return allowsCommandCenter && target.direction === "right"
304	        ? { direction: "right", destination: { kind: "command-center" } }
305	        : null;
306	    }
307	    const content = findPaneContent(panes, paneId);
308	    return content === null
309	      ? null
310	      : {
311	          direction: target.direction,
312	          destination: { kind: "pane", paneId, content },
313	        };
314	  };
315	
316	  const resolveCommit = (
317	    session: SwipeSession,
318	    current: SwipePreview,
319	  ): SwipeCommit | null => {
320	    const outcome = decideWorkspaceSwipe({
321	      deltaX: session.deltaX,
322	      // Only a finger still moving at release may fling: pausing before lifting
323	      // is a deliberate "not far enough", and must cancel.
324	      velocityX: readReleaseVelocity(
325	        session.velocityX,
326	        Date.now() - session.lastTimeMs,
327	      ),
328	      width: session.width,
329	      allowsCommandCenter,
330	    });
