332	    if (
333	      outcome.kind === "command-center" &&
334	      destination.kind === "command-center"
335	    ) {
336	      return { announcement: "Command Center", run: onOpenCommandCenter };
337	    }
338	    if (outcome.kind !== "pane") {
339	      return null;
340	    }
341	    if (destination.kind === "pane") {
342	      return {
343	        announcement: describeWorkspacePosition(panes, destination.paneId),
344	        run: () => onFocusPane(destination.paneId),
345	      };
346	    }
347	    if (destination.kind === "return") {
348	      return {
349	        announcement: describeWorkspacePosition(panes, destination.paneId),
350	        run: onReturnFromCommandCenter,
351	      };
352	    }
353	    return null;
354	  };
355	
356	  const handlePointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
