358	    if (
359	      host === null ||
360	      event.defaultPrevented ||
361	      event.pointerType !== "touch" ||
362	      event.button !== 0 ||
363	      sessionRef.current !== null ||
364	      settleTimerRef.current !== null ||
365	      isBlockingOverlayOpen(host.ownerDocument) ||
366	      shouldIgnoreWorkspaceSwipeTarget(event.target)
367	    ) {
368	      return;
369	    }
370	    const startedContentKey = contentKey;
371	
372	    const nowMs = Date.now();
373	    const session: SwipeSession = {
374	      pointerId: event.pointerId,
375	      startX: event.clientX,
376	      startY: event.clientY,
377	      // The laid-out surface owns the physical width; the viewport is the
378	      // fallback for environments that report no box (jsdom, pre-layout).
379	      width: host.getBoundingClientRect().width || window.innerWidth,
380	      deltaX: 0,
381	      lastX: event.clientX,
382	      lastTimeMs: nowMs,
383	      velocityX: 0,
384	      isDragging: false,
385	    };
386	    sessionRef.current = session;
387	
388	    const teardown = () => {
389	      window.removeEventListener("pointermove", onMove);
390	      window.removeEventListener("pointerup", onPointerUp);
391	      window.removeEventListener("pointercancel", onPointerAbort);
392	      window.removeEventListener("lostpointercapture", onPointerAbort);
