394	      window.removeEventListener("orientationchange", onEnvironmentChange);
395	      teardownRef.current = null;
396	    };
397	
398	    const finish = (commit: boolean) => {
399	      if (sessionRef.current !== session) {
400	        return;
401	      }
402	      teardown();
403	      releasePointer(host, session.pointerId);
404	      sessionRef.current = null;
405	
406	      const current = previewRef.current;
407	      if (!session.isDragging || current === null) {
408	        restLayers();
409	        return;
410	      }
411	      const committed = commit ? resolveCommit(session, current) : null;
412	      if (committed === null) {
413	        applyMotion(0, session.width, true);
414	        afterSettle(restLayers);
415	        return;
416	      }
417	      applyMotion(
418	        current.direction === "right" ? session.width : -session.width,
419	        session.width,
420	        true,
421	      );
422	      afterSettle(() => {
423	        restLayers();
424	        // The surface changed while the settle ran: the destination this gesture
425	        // chose no longer describes what the user is looking at.
426	        if (contentKeyRef.current !== startedContentKey) {
427	          return;
428	        }
429	        if (committed.announcement !== null) {
430	          setAnnouncement(committed.announcement);
431	        }
432	        committed.run();
433	      });
434	    };
435	
436	    const onMove = (moveEvent: PointerEvent) => {
437	      if (
438	        sessionRef.current !== session ||
439	        moveEvent.pointerId !== session.pointerId
440	      ) {
441	        return;
442	      }
443	      const deltaX = moveEvent.clientX - session.startX;
444	      const deltaY = moveEvent.clientY - session.startY;
445	
446	      if (!session.isDragging) {
447	        if (abandonsWorkspaceSwipe(deltaX, deltaY)) {
448	          finish(false);
449	          return;
450	        }
451	        if (!hasWorkspaceSwipeIntent(deltaX, deltaY)) {
452	          return;
453	        }
454	        session.isDragging = true;
455	        capturePointer(host, session.pointerId);
456	      }
457	
458	      // touch-action already reserves the horizontal axis; this also stops a
459	      // browser-level swipe from starting once the gesture owns the pointer.
460	      if (moveEvent.cancelable) {
461	        moveEvent.preventDefault();
462	      }
463	
464	      const nowMs = Date.now();
465	      const elapsedMs = nowMs - session.lastTimeMs;
466	      if (elapsedMs > 0) {
467	        session.velocityX =
468	          ((moveEvent.clientX - session.lastX) / elapsedMs) * 1000;
469	        session.lastX = moveEvent.clientX;
470	        session.lastTimeMs = nowMs;
471	      }
472	      session.deltaX = deltaX;
473	
474	      const nextPreview = resolvePreview(deltaX, session.width);
475	      if (!isSamePreview(nextPreview, previewRef.current)) {
476	        previewRef.current = nextPreview;
477	        // Mount the shell synchronously so the first frame of travel already
478	        // carries it, instead of flashing the empty page behind the surface.
479	        flushSync(() =>
480	          setPreviewState(
481	            nextPreview === null
482	              ? null
483	              : { contentKey: startedContentKey, preview: nextPreview },
484	          ),
485	        );
486	      }
487	      applyMotion(deltaX, session.width, false);
488	    };
489	    // A second finger produces its own pointer events on the same window. Only
490	    // the pointer that started this gesture may end it, or an unrelated tap
491	    // would commit or cancel the drag under the first finger.
492	    const isTrackedPointer = (endEvent: PointerEvent) =>
493	      endEvent.pointerId === session.pointerId;
494	    const onPointerUp = (endEvent: PointerEvent) => {
495	      if (isTrackedPointer(endEvent)) {
496	        finish(true);
497	      }
498	    };
499	    const onPointerAbort = (endEvent: PointerEvent) => {
500	      if (isTrackedPointer(endEvent)) {
501	        finish(false);
502	      }
503	    };
504	    const onEnvironmentChange = () => finish(false);
505	
506	    teardownRef.current = teardown;
507	    window.addEventListener("pointermove", onMove, { passive: false });
508	    window.addEventListener("pointerup", onPointerUp);
509	    window.addEventListener("pointercancel", onPointerAbort);
510	    window.addEventListener("lostpointercapture", onPointerAbort);
511	    window.addEventListener("resize", onEnvironmentChange);
512	    window.addEventListener("orientationchange", onEnvironmentChange);
513	  };
514	
515	  return (
516	    <div
517	      ref={hostRef}
518	      data-workspace-swipe-host=""
519	      onPointerDown={handlePointerDown}
520	      // Cancels the app layout's page padding so the surface travels to the
521	      // real screen edges; each layer re-applies it (see SWIPE_LAYER_CLASS).
522	      className="relative -m-4 flex min-h-0 min-w-0 flex-1 touch-pan-y overflow-hidden md:-m-5"
523	    >
524	      <div
525	        ref={sourceRef}
526	        data-workspace-swipe-surface="source"
527	        className={SWIPE_LAYER_CLASS}
528	      >
529	        {children}
530	      </div>
531	      {preview !== null ? (
532	        <div
533	          ref={previewLayerRef}
534	          aria-hidden
535	          data-workspace-swipe-surface="preview"
536	          className={`pointer-events-none absolute inset-0 select-none ${SWIPE_LAYER_CLASS}`}
537	        >
538	          <CompactWorkspacePreviewSurface
539	            content={
540	              preview.destination.kind === "command-center"
541	                ? null
542	                : preview.destination.content
543	            }
544	          />
545	        </div>
546	      ) : null}
547	      <span
548	        aria-live="polite"
549	        aria-atomic="true"
550	        className="sr-only"
551	        data-testid="workspace-swipe-position"
552	      >
553	        {announcement}
554	      </span>
555	    </div>
556	  );
557	}
